import {menu,normalizeCart,changeQuantity,summarize,validateCheckout} from './order.9de6c01c00e5.mjs';
const money=value=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(value);
const storageKey='kuhnya-ryadom-cart-v1';
let cart={},mode='pickup',storageAvailable=true,toastTimer;
try{cart=normalizeCart(JSON.parse(localStorage.getItem(storageKey)||'{}'));}catch{cart={};}
const dialog=document.querySelector('#cart'),form=document.querySelector('#checkout');
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav');
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);});
nav.addEventListener('click',event=>{if(event.target.closest('a')){nav.classList.remove('is-open');toggle.setAttribute('aria-expanded','false');}});
function element(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
const grid=document.querySelector('#menu-grid');
for(const item of menu){const card=element('article','menu-card');card.dataset.menuCategory=item.category;const img=element('img');img.src=`images/${item.image}`;img.alt=item.name;img.width=1536;img.height=1024;img.loading='lazy';const heading=element('div','menu-card-head');heading.append(element('h3',null,item.name),element('span',null,item.weight));const details=element('details');details.append(element('summary',null,'Состав и аллергены'),element('p',null,`Аллергены: ${item.allergens}. ${item.description}`));const bottom=element('div','menu-card-bottom');const add=element('button','add-button','+ В заказ');add.type='button';add.dataset.add=item.id;add.setAttribute('aria-label',`Добавить: ${item.name}`);bottom.append(element('strong',null,money(item.price)),add);card.append(img,heading,element('p',null,item.description),details,bottom);grid.append(card);}
for(const button of document.querySelectorAll('[data-category]'))button.addEventListener('click',()=>{let visible=0;for(const card of grid.children){card.hidden=button.dataset.category!=='all'&&card.dataset.menuCategory!==button.dataset.category;if(!card.hidden)visible++;}for(const filter of document.querySelectorAll('[data-category]'))filter.setAttribute('aria-pressed',String(filter===button));document.querySelector('#menu-status').textContent=`Показано блюд и напитков: ${visible}`;});
function save(){try{localStorage.setItem(storageKey,JSON.stringify(cart));storageAvailable=true;}catch{storageAvailable=false;}document.querySelector('#storage-note').hidden=storageAvailable;}
function toast(message){const node=document.querySelector('#toast');clearTimeout(toastTimer);node.textContent=message;node.classList.add('visible');toastTimer=setTimeout(()=>node.classList.remove('visible'),2500);}
function updateHeader(){const total=summarize(cart,mode);for(const node of document.querySelectorAll('[data-cart-count]'))node.textContent=String(total.count);document.querySelector('[data-cart-total]').textContent=money(total.total);document.querySelector('.mobile-cart').hidden=!total.count;document.querySelector('.cart-button').setAttribute('aria-label',`Открыть заказ, товаров: ${total.count}`);}
function updateTotals(){const total=summarize(cart,mode);document.querySelector('#subtotal').textContent=money(total.subtotal);document.querySelector('#delivery-price').textContent=mode==='pickup'?'Самовывоз':total.delivery?money(total.delivery):'Бесплатно';document.querySelector('#total').textContent=money(total.total);document.querySelector('#submit-total').textContent=money(total.total);document.querySelector('#address-field').hidden=mode!=='delivery';form.elements.address.required=mode==='delivery';if(mode!=='delivery'){form.elements.address.removeAttribute('aria-invalid');document.querySelector('#address-error').textContent='';}document.querySelector('#fulfillment-note').textContent=mode==='pickup'?'Самовывоз: ул. Солнечная, 8. Пример готовности: 20–30 минут.':`Пример доставки: 45–60 минут. ${total.subtotal<1500?'До бесплатной доставки ещё '+money(1500-total.subtotal)+'.':'Доставка бесплатно.'}`;updateHeader();}
function renderCart(){const list=document.querySelector('#cart-items');list.replaceChildren();for(const [id,quantity] of Object.entries(cart)){const item=menu.find(item=>item.id===id);const row=element('article','cart-item');const img=element('img');img.src=`images/${item.image}`;img.alt='';img.width=76;img.height=76;const body=element('div');const controls=element('div','cart-item-controls');const stepper=element('div','stepper');for(const [delta,label,text] of [[-1,`Уменьшить: ${item.name}`,'−'],[1,`Увеличить: ${item.name}`,'+']]){const b=element('button',null,text);b.type='button';b.dataset.quantity=id;b.dataset.delta=String(delta);b.setAttribute('aria-label',label);b.disabled=delta===1&&quantity>=20;if(delta===-1)stepper.append(b,element('span',null,String(quantity)));else stepper.append(b);}const remove=element('button','remove-item','Удалить');remove.type='button';remove.dataset.remove=id;remove.setAttribute('aria-label',`Удалить: ${item.name}`);controls.append(stepper,remove);body.append(element('h3',null,item.name),element('p','item-price',`${money(item.price)} × ${quantity} = ${money(item.price*quantity)}`),controls);row.append(img,body);list.append(row);}const empty=!summarize(cart).count;document.querySelector('#cart-empty').hidden=!empty;document.querySelector('#cart-filled').hidden=empty;updateTotals();}
function mutate(id,delta){cart=changeQuantity(cart,id,delta);save();updateHeader();if(dialog.open)renderCart();}
document.addEventListener('click',event=>{const add=event.target.closest('[data-add]');if(add){const item=menu.find(item=>item.id===add.dataset.add);if((cart[item.id]||0)>=20){toast('Максимум 20 порций одного блюда.');return;}mutate(item.id,1);toast(`В заказе: ${item.name}`);return;}const step=event.target.closest('[data-quantity]');if(step){const id=step.dataset.quantity,delta=step.dataset.delta;mutate(id,Number(delta));const replacement=dialog.querySelector(`[data-quantity="${id}"][data-delta="${delta}"]`);if(replacement&&!replacement.disabled)replacement.focus();else (dialog.querySelector('[data-quantity]')||dialog.querySelector('.close')).focus();return;}const remove=event.target.closest('[data-remove]');if(remove){cart=changeQuantity(cart,remove.dataset.remove,-20);save();renderCart();(dialog.querySelector('[data-remove]')||dialog.querySelector('#back-to-menu')).focus();}});
for(const button of document.querySelectorAll('[data-cart-open]'))button.addEventListener('click',()=>{document.querySelector('#order-success').hidden=true;document.querySelector('#cart-content').hidden=false;renderCart();dialog.showModal();document.body.classList.add('modal-open');});
document.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');form.reset();clearErrors();mode='pickup';document.querySelector('[name=fulfillment][value=pickup]').checked=true;updateTotals();});
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right)dialog.close();}});
function returnToMenu(){dialog.close();document.querySelector('#menu').scrollIntoView();}
document.querySelector('#back-to-menu').addEventListener('click',returnToMenu);
document.querySelector('#new-order').addEventListener('click',returnToMenu);
for(const radio of document.querySelectorAll('[name=fulfillment]'))radio.addEventListener('change',()=>{mode=radio.value;updateTotals();});
function clearErrors(){for(const name of ['name','phone','address','acknowledged']){document.querySelector(`#${name}-error`).textContent='';form.elements[name].removeAttribute('aria-invalid');}document.querySelector('#checkout-error').textContent='';}
form.addEventListener('input',event=>{const input=event.target;const error=document.getElementById(`${input.name}-error`);if(error){error.textContent='';input.removeAttribute('aria-invalid');}});
form.addEventListener('submit',event=>{event.preventDefault();clearErrors();const data={name:form.elements.name.value,phone:form.elements.phone.value,address:form.elements.address.value,mode,acknowledged:form.elements.acknowledged.checked};const errors=validateCheckout(data,cart);if(Object.keys(errors).length){for(const [name,message] of Object.entries(errors)){const node=document.querySelector(`#${name}-error`);if(node){node.textContent=message;form.elements[name].setAttribute('aria-invalid','true');}else document.querySelector('#checkout-error').textContent=message;}const first=Object.keys(errors).find(name=>form.elements[name]);if(first)form.elements[first].focus();return;}const total=summarize(cart,mode);const summary=document.querySelector('#order-summary');summary.replaceChildren(element('p',null,Object.entries(cart).map(([id,q])=>`${menu.find(item=>item.id===id).name} × ${q}`).join(', ')),element('p',null,`Способ получения: ${mode==='pickup'?'самовывоз':'доставка'}.`),element('p',null,`Сумма примера: ${money(total.total)}.`));cart={};save();updateHeader();form.reset();document.querySelector('#cart-content').hidden=true;const success=document.querySelector('#order-success');success.hidden=false;success.focus();dialog.scrollTop=0;});
window.addEventListener('storage',event=>{if(event.key===storageKey||event.key===null){try{cart=normalizeCart(JSON.parse(localStorage.getItem(storageKey)||'{}'));}catch{cart={};}updateHeader();if(dialog.open&&!document.querySelector('#cart-content').hidden)renderCart();}});
updateHeader();
